/* ==========================================================================
   高精度リアルタイム アナログ時計 Webアプリ スタイルシート
   ========================================================================== */

:root {
  --font-family-base: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-family-mono: "SF Mono", Monaco, Inconsolata, "Roboto Mono", "Courier New", monospace;
  --font-family-clock: "Cinzel", "Georgia", "Times New Roman", serif;

  /* デフォルト・テーマカラー (Classic) */
  --bg-primary: #1e2430;
  --bg-card: #283042;
  --bg-card-glow: rgba(56, 189, 248, 0.15);
  --clock-bg: #f8fafc;
  --clock-border: #cbd5e1;
  --clock-rim: #64748b;
  --clock-numbers: #1e293b;
  --clock-marks: #94a3b8;
  --clock-major-marks: #334155;
  --hour-hand: #0f172a;
  --minute-hand: #1e293b;
  --second-hand: #ef4444;
  --pivot-outer: #0f172a;
  --pivot-inner: #ef4444;
  --text-main: #f1f5f9;
  --text-muted: #94a3b8;
  --control-bg: rgba(15, 23, 42, 0.6);
  --control-border: #334155;
  --control-active: #3b82f6;
  --control-active-text: #ffffff;
  --accent: #38bdf8;
}

/* テーマ別変数 */
.theme-classic {
  --bg-primary: #0f172a;
  --bg-card: #1e293b;
  --bg-card-glow: rgba(99, 102, 241, 0.12);
  --clock-bg: #fdfdfd;
  --clock-border: #94a3b8;
  --clock-rim: #475569;
  --clock-numbers: #0f172a;
  --clock-marks: #94a3b8;
  --clock-major-marks: #1e293b;
  --hour-hand: #0f172a;
  --minute-hand: #334155;
  --second-hand: #dc2626;
  --pivot-outer: #0f172a;
  --pivot-inner: #dc2626;
  --text-main: #f1f5f9;
  --text-muted: #94a3b8;
  --control-bg: rgba(15, 23, 42, 0.6);
  --control-border: #334155;
  --control-active: #3b82f6;
  --control-active-text: #ffffff;
  --accent: #38bdf8;
}

.theme-dark {
  --bg-primary: #090a0f;
  --bg-card: #131722;
  --bg-card-glow: rgba(59, 130, 246, 0.18);
  --clock-bg: #111827;
  --clock-border: #1f2937;
  --clock-rim: #374151;
  --clock-numbers: #f3f4f6;
  --clock-marks: #4b5563;
  --clock-major-marks: #9ca3af;
  --hour-hand: #f9fafb;
  --minute-hand: #e5e7eb;
  --second-hand: #06b6d4;
  --pivot-outer: #1f2937;
  --pivot-inner: #06b6d4;
  --text-main: #f9fafb;
  --text-muted: #9ca3af;
  --control-bg: rgba(9, 10, 15, 0.7);
  --control-border: #1f2937;
  --control-active: #0284c7;
  --control-active-text: #ffffff;
  --accent: #06b6d4;
}

.theme-gold {
  --bg-primary: #12100e;
  --bg-card: #201a15;
  --bg-card-glow: rgba(245, 158, 11, 0.2);
  --clock-bg: #1c1814;
  --clock-border: #785324;
  --clock-rim: #b4833e;
  --clock-numbers: #fbbf24;
  --clock-marks: #926a2f;
  --clock-major-marks: #f59e0b;
  --hour-hand: #fbbf24;
  --minute-hand: #d97706;
  --second-hand: #e11d48;
  --pivot-outer: #785324;
  --pivot-inner: #e11d48;
  --text-main: #fef3c7;
  --text-muted: #b4833e;
  --control-bg: rgba(18, 16, 14, 0.75);
  --control-border: #785324;
  --control-active: #d97706;
  --control-active-text: #ffffff;
  --accent: #fbbf24;
}

.theme-minimal {
  --bg-primary: #f8fafc;
  --bg-card: #ffffff;
  --bg-card-glow: rgba(148, 163, 184, 0.2);
  --clock-bg: #ffffff;
  --clock-border: #e2e8f0;
  --clock-rim: #cbd5e1;
  --clock-numbers: #475569;
  --clock-marks: #cbd5e1;
  --clock-major-marks: #64748b;
  --hour-hand: #1e293b;
  --minute-hand: #475569;
  --second-hand: #64748b;
  --pivot-outer: #334155;
  --pivot-inner: #64748b;
  --text-main: #0f172a;
  --text-muted: #64748b;
  --control-bg: rgba(241, 245, 249, 0.85);
  --control-border: #cbd5e1;
  --control-active: #0f172a;
  --control-active-text: #ffffff;
  --accent: #0f172a;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-family-base);
  background-color: var(--bg-primary);
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: center;
  line-height: 1.5;
  transition: background-color 0.4s ease, color 0.4s ease;
  overflow-x: hidden;
}

/* 全体ラッパー */
.clock-app {
  width: 100%;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  background: radial-gradient(circle at 50% 20%, rgba(56, 189, 248, 0.05), transparent 70%);
}

.clock-container {
  width: 100%;
  max-width: 460px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 20px;
}

/* 時計本体カード */
.clock-card {
  width: 100%;
  background: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 28px;
  padding: 28px 24px 24px;
  box-shadow: 0 20px 40px -15px rgba(0, 0, 0, 0.5),
              0 0 35px var(--bg-card-glow);
  display: flex;
  flex-direction: column;
  align-items: center;
  position: relative;
  transition: background 0.4s ease, box-shadow 0.4s ease, border-color 0.4s ease;
}

/* SVG アナログ時計盤 */
.clock-svg {
  width: 100%;
  max-width: 330px;
  aspect-ratio: 1 / 1;
  display: block;
  filter: drop-shadow(0 12px 24px rgba(0, 0, 0, 0.35));
  user-select: none;
}

/* 時計盤の盤面背景 */
.clock-face {
  fill: var(--clock-bg);
  stroke: var(--clock-rim);
  stroke-width: 4;
  transition: fill 0.3s ease, stroke 0.3s ease;
}

/* 目盛り */
.clock-mark {
  stroke: var(--clock-marks);
  stroke-width: 1.5;
  stroke-linecap: round;
  transition: stroke 0.3s ease;
}

.clock-mark-major {
  stroke: var(--clock-major-marks);
  stroke-width: 3.5;
  stroke-linecap: round;
  transition: stroke 0.3s ease;
}

/* 数字 */
.clock-number {
  fill: var(--clock-numbers);
  font-family: var(--font-family-clock);
  font-size: 19px;
  font-weight: 600;
  text-anchor: middle;
  dominant-baseline: central;
  transition: fill 0.3s ease;
}

/* 針共通設定 */
.clock-hand {
  stroke-linecap: round;
  transform-origin: 150px 150px;
  filter: drop-shadow(0 2px 4px rgba(0, 0, 0, 0.3));
  will-change: transform;
}

/* 時針 */
.hand-hour {
  stroke: var(--hour-hand);
  stroke-width: 5.5;
  transition: stroke 0.3s ease;
}

/* 分針 */
.hand-minute {
  stroke: var(--minute-hand);
  stroke-width: 3.8;
  transition: stroke 0.3s ease;
}

/* 秒針 */
.hand-second {
  stroke: var(--second-hand);
  stroke-width: 1.8;
  filter: drop-shadow(0 2px 5px rgba(239, 68, 68, 0.4));
  transition: stroke 0.3s ease;
}

/* 針の軸（センターピボット） */
.hand-pivot {
  fill: var(--pivot-outer);
  stroke: rgba(255, 255, 255, 0.2);
  stroke-width: 1;
  transition: fill 0.3s ease;
}

.hand-pivot-inner {
  fill: var(--pivot-inner);
  transition: fill 0.3s ease;
}

/* デジタル表示 */
.digital-display {
  margin-top: 18px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.digital-time {
  font-family: var(--font-family-mono);
  font-size: 28px;
  font-weight: 700;
  letter-spacing: 2px;
  color: var(--text-main);
  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.3);
}

.digital-date {
  font-size: 14px;
  font-weight: 500;
  color: var(--text-muted);
  letter-spacing: 0.5px;
}

/* コントロールパネル */
.controls-panel {
  width: 100%;
  background: var(--bg-card);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 20px;
  padding: 18px 20px;
  display: flex;
  flex-direction: column;
  gap: 14px;
  box-shadow: 0 10px 25px -10px rgba(0, 0, 0, 0.3);
}

.control-group {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.control-label {
  font-size: 13.5px;
  font-weight: 500;
  color: var(--text-muted);
  white-space: nowrap;
}

/* ボタングループ */
.toggle-group,
.button-group {
  display: flex;
  gap: 6px;
}

/* セレクトコントロール */
.select-control {
  background: var(--control-bg);
  color: var(--text-main);
  border: 1px solid var(--control-border);
  border-radius: 10px;
  padding: 6px 12px;
  font-size: 13.5px;
  font-weight: 500;
  cursor: pointer;
  outline: none;
  transition: border-color 0.2s, background 0.2s;
  min-height: 36px;
}

.select-control:focus {
  border-color: var(--accent);
}

/* トグルボタングループ & 単体トグルボタン */
.toggle-button {
  background: var(--control-bg);
  color: var(--text-muted);
  border: 1px solid var(--control-border);
  border-radius: 8px;
  padding: 6px 14px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s ease;
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  user-select: none;
}

.toggle-button:hover {
  background: rgba(255, 255, 255, 0.08);
  color: var(--text-main);
}

.toggle-button.active {
  background: var(--control-active);
  color: var(--control-active-text);
  border-color: var(--control-active);
  box-shadow: 0 2px 8px rgba(59, 130, 246, 0.35);
}

/* サウンド専用ボタン */
.sound-btn {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.sound-btn.active {
  background: #10b981;
  border-color: #10b981;
  color: #ffffff;
  box-shadow: 0 2px 8px rgba(16, 185, 129, 0.35);
}

/* フッター情報 */
.footer-info {
  font-size: 12px;
  color: var(--text-muted);
  text-align: center;
  line-height: 1.6;
  opacity: 0.8;
  margin-top: 4px;
}

/* レスポンシブ対応 (360px以下の小型画面) */
@media (max-width: 400px) {
  .clock-card {
    padding: 20px 16px 16px;
    border-radius: 20px;
  }

  .digital-time {
    font-size: 24px;
  }

  .digital-date {
    font-size: 12.5px;
  }

  .controls-panel {
    padding: 14px 16px;
  }

  .control-label {
    font-size: 12.5px;
  }

  .toggle-button {
    padding: 5px 10px;
    font-size: 12px;
  }
}

export type ThemeType = 'classic' | 'dark' | 'gold' | 'minimal';

export type MovementType = 'smooth' | 'step';

export interface ThemeOption {
  id: ThemeType;
  label: string;
}

export interface ClockSettings {
  theme: ThemeType;
  movement: MovementType;
  showDigital: boolean;
  showDate: boolean;
  soundEnabled: boolean;
  volume?: number;
}

export interface TimeData {
  hours: number;
  minutes: number;
  seconds: number;
  milliseconds: number;
  dateString: string;
  timeString: string;
  timestamp: number;
  rawDate?: Date;
}

import { FC, useMemo } from 'react';
import { TimeData, ThemeType, MovementType } from '../types';

interface AnalogClockProps {
  time: TimeData;
  theme?: ThemeType;
  movement?: MovementType;
}

interface DialMark {
  id: number;
  rotation: number;
  isMajor: boolean;
  y2: number;
}

// 60本の目盛り定義（中心 150, 150 を基準にSVG rotateで配置）
const DIAL_MARKS: DialMark[] = Array.from({ length: 60 }, (_, i) => {
  const isMajor = i % 5 === 0;
  return {
    id: i,
    rotation: i * 6,
    isMajor,
    y2: isMajor ? 28 : 22,
  };
});

interface DialNumber {
  num: number;
  x: number;
  y: number;
}

// 1〜12の文字盤数字の配置座標定義
const DIAL_NUMBERS: DialNumber[] = Array.from({ length: 12 }, (_, idx) => {
  const num = idx + 1;
  const angle = num * 30;
  const rad = (angle * Math.PI) / 180;
  const radius = 104;
  return {
    num,
    x: Number((150 + radius * Math.sin(rad)).toFixed(3)),
    y: Number((150 - radius * Math.cos(rad)).toFixed(3)),
  };
});

const AnalogClock: FC<AnalogClockProps> = ({
  time,
  theme,
  movement = 'smooth',
}) => {
  const { hours = 0, minutes = 0, seconds = 0, milliseconds = 0 } = time ?? {};

  // 運針タイプ（滑らか / ステップ）に応じた針の角度計算
  const angles = useMemo(() => {
    let secondAngle: number;
    let minuteAngle: number;
    let hourAngle: number;

    if (movement === 'smooth') {
      const preciseSeconds = seconds + milliseconds / 1000;
      const preciseMinutes = minutes + preciseSeconds / 60;
      const preciseHours = (hours % 12) + preciseMinutes / 60;

      secondAngle = preciseSeconds * 6;
      minuteAngle = preciseMinutes * 6;
      hourAngle = preciseHours * 30;
    } else {
      secondAngle = seconds * 6;
      const stepMinutes = minutes + seconds / 60;
      const stepHours = (hours % 12) + stepMinutes / 60;

      minuteAngle = stepMinutes * 6;
      hourAngle = stepHours * 30;
    }

    return {
      second: secondAngle,
      minute: minuteAngle,
      hour: hourAngle,
    };
  }, [hours, minutes, seconds, milliseconds, movement]);

  return (
    <svg
      className={`clock-svg${theme ? ` theme-${theme}` : ''}`}
      viewBox="0 0 300 300"
      aria-label="リアルタイム アナログ時計"
      role="img"
      data-theme={theme}
    >
      {/* 盤面本体 */}
      <circle cx="150" cy="150" r="142" className="clock-face" />

      {/* 60本の目盛り */}
      {DIAL_MARKS.map((mark) => (
        <line
          key={mark.id}
          x1="150"
          y1="14"
          x2="150"
          y2={mark.y2}
          className={mark.isMajor ? 'clock-mark-major' : 'clock-mark'}
          transform={`rotate(${mark.rotation} 150 150)`}
        />
      ))}

      {/* 1〜12の数字 */}
      {DIAL_NUMBERS.map(({ num, x, y }) => (
        <text
          key={num}
          x={x}
          y={y}
          className="clock-number"
        >
          {num}
        </text>
      ))}

      {/* 時針 */}
      <line
        x1="150"
        y1="162"
        x2="150"
        y2="78"
        className="clock-hand hand-hour"
        transform={`rotate(${angles.hour} 150 150)`}
      />

      {/* 分針 */}
      <line
        x1="150"
        y1="166"
        x2="150"
        y2="46"
        className="clock-hand hand-minute"
        transform={`rotate(${angles.minute} 150 150)`}
      />

      {/* 秒針（カウンターウェイト付き） */}
      <g transform={`rotate(${angles.second} 150 150)`}>
        <line
          x1="150"
          y1="174"
          x2="150"
          y2="30"
          className="clock-hand hand-second"
        />
      </g>

      {/* センターピボット（軸） */}
      <circle cx="150" cy="150" r="7.5" className="hand-pivot" />
      <circle cx="150" cy="150" r="3.2" className="hand-pivot-inner" />
    </svg>
  );
};

export default AnalogClock;

import { FC, ChangeEvent } from 'react';
import { ClockSettings, ThemeType, MovementType } from '../types';

interface ClockControlsProps {
  settings: ClockSettings;
  onUpdateSettings: <K extends keyof ClockSettings>(key: K, value: ClockSettings[K]) => void;
}

const ClockControls: FC<ClockControlsProps> = ({
  settings,
  onUpdateSettings,
}) => {
  const handleThemeChange = (e: ChangeEvent<HTMLSelectElement>) => {
    onUpdateSettings('theme', e.target.value as ThemeType);
  };

  const handleMovementChange = (movement: MovementType) => {
    onUpdateSettings('movement', movement);
  };

  const handleToggleDigital = () => {
    onUpdateSettings('showDigital', !settings.showDigital);
  };

  const handleToggleDate = () => {
    onUpdateSettings('showDate', !settings.showDate);
  };

  const handleToggleSound = () => {
    onUpdateSettings('soundEnabled', !settings.soundEnabled);
  };

  return (
    <div className="controls-panel">
      {/* テーマ選択 */}
      <div className="control-group">
        <label htmlFor="theme-select" className="control-label">
          文字盤テーマ
        </label>
        <select
          id="theme-select"
          className="select-control"
          value={settings.theme}
          onChange={handleThemeChange}
        >
          <option value="classic">クラシック (Classic)</option>
          <option value="dark">ダーク (Dark)</option>
          <option value="gold">アンティークゴールド (Gold)</option>
          <option value="minimal">ミニマル (Minimal)</option>
        </select>
      </div>

      {/* 運針切り替え（スイープ / ステップ） */}
      <div className="control-group">
        <span className="control-label" id="movement-mode-label">針の動き</span>
        <div
          className="toggle-group"
          role="radiogroup"
          aria-labelledby="movement-mode-label"
        >
          <button
            type="button"
            role="radio"
            aria-checked={settings.movement === 'smooth'}
            aria-label="スイープ運針（滑らか）"
            className={`toggle-button ${settings.movement === 'smooth' ? 'active' : ''}`}
            onClick={() => handleMovementChange('smooth')}
          >
            スイープ (滑らか)
          </button>
          <button
            type="button"
            role="radio"
            aria-checked={settings.movement === 'step'}
            aria-label="ステップ運針（1秒毎）"
            className={`toggle-button ${settings.movement === 'step' ? 'active' : ''}`}
            onClick={() => handleMovementChange('step')}
          >
            ステップ (1秒毎)
          </button>
        </div>
      </div>

      {/* デジタル時計・日付の表示切り替え */}
      <div className="control-group">
        <span className="control-label" id="display-options-label">追加表示</span>
        <div className="toggle-group" aria-labelledby="display-options-label">
          <button
            type="button"
            className={`toggle-button ${settings.showDigital ? 'active' : ''}`}
            onClick={handleToggleDigital}
            aria-pressed={settings.showDigital}
            aria-label={`デジタル時刻表示: ${settings.showDigital ? '現在オン、クリックでオフ' : '現在オフ、クリックでオン'}`}
          >
            時刻表示: {settings.showDigital ? 'ON' : 'OFF'}
          </button>
          <button
            type="button"
            className={`toggle-button ${settings.showDate ? 'active' : ''}`}
            onClick={handleToggleDate}
            aria-pressed={settings.showDate}
            aria-label={`日付表示: ${settings.showDate ? '現在オン、クリックでオフ' : '現在オフ、クリックでオン'}`}
          >
            日付: {settings.showDate ? 'ON' : 'OFF'}
          </button>
        </div>
      </div>

      {/* 秒針音切り替え */}
      <div className="control-group">
        <span className="control-label" id="sound-label">効果音</span>
        <button
          type="button"
          className={`toggle-button sound-btn ${settings.soundEnabled ? 'active' : ''}`}
          onClick={handleToggleSound}
          aria-pressed={settings.soundEnabled}
          aria-labelledby="sound-label"
          aria-label={`秒針カチカチ音: ${settings.soundEnabled ? '現在オン、クリックでオフ' : '現在オフ、クリックでオン'}`}
        >
          {settings.soundEnabled ? '🔔 秒針音 ON' : '🔕 秒針音 OFF'}
        </button>
      </div>
    </div>
  );
};

export default ClockControls;

import { FC, useState, useEffect, useRef, useCallback } from 'react';
import AnalogClock from './components/AnalogClock';
import ClockControls from './components/ClockControls';
import { ClockSettings, TimeData } from './types';
import './index.css';

const DEFAULT_SETTINGS: ClockSettings = {
  theme: 'classic',
  movement: 'smooth',
  showDigital: true,
  showDate: true,
  soundEnabled: false,
};

const padZero = (num: number): string => num.toString().padStart(2, '0');

const formatTimeData = (date: Date): TimeData => {
  const hours = date.getHours();
  const minutes = date.getMinutes();
  const seconds = date.getSeconds();
  const milliseconds = date.getMilliseconds();

  const year = date.getFullYear();
  const month = date.getMonth() + 1;
  const day = date.getDate();
  const dayNames = ['日', '月', '火', '水', '木', '金', '土'];
  const dayOfWeek = dayNames[date.getDay()];

  return {
    hours,
    minutes,
    seconds,
    milliseconds,
    dateString: `${year}年${month}月${day}日 (${dayOfWeek})`,
    timeString: `${padZero(hours)}:${padZero(minutes)}:${padZero(seconds)}`,
    timestamp: date.getTime(),
    rawDate: date,
  };
};

const App: FC = () => {
  const [settings, setSettings] = useState<ClockSettings>(() => {
    try {
      const saved = localStorage.getItem('analog-clock-settings');
      if (saved) {
        const parsed = JSON.parse(saved);
        return {
          ...DEFAULT_SETTINGS,
          ...parsed,
          // 音声自動再生のブラウザポリシーを考慮し、初期化時は音声を安全にデフォルトOFFか復元値
          soundEnabled: Boolean(parsed.soundEnabled),
        };
      }
    } catch {
      // localStorageが利用できない環境への安全対応
    }
    return DEFAULT_SETTINGS;
  });

  const [time, setTime] = useState<TimeData>(() => formatTimeData(new Date()));

  // Web Audio API 用のRef
  const audioCtxRef = useRef<AudioContext | null>(null);
  const lastSecondRef = useRef<number>(-1);

  // localStorage保存
  useEffect(() => {
    try {
      localStorage.setItem('analog-clock-settings', JSON.stringify(settings));
    } catch {
      // クオータ超過やプライベートブラウズ対応
    }
  }, [settings]);

  // 設定更新ハンドラ
  const handleUpdateSettings = useCallback(
    <K extends keyof ClockSettings>(key: K, value: ClockSettings[K]) => {
      setSettings((prev) => ({
        ...prev,
        [key]: value,
      }));

      // サウンド有効化時にAudioContextを初期化またはresume
      if (key === 'soundEnabled' && value === true) {
        if (!audioCtxRef.current) {
          const AudioContextClass = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
          if (AudioContextClass) {
            audioCtxRef.current = new AudioContextClass();
          }
        }
        if (audioCtxRef.current && audioCtxRef.current.state === 'suspended') {
          audioCtxRef.current.resume().catch(() => {});
        }
      }
    },
    []
  );

  // カチカチ音（チクタク音）の生成
  const playTickSound = useCallback((isHighTick: boolean) => {
    try {
      if (!audioCtxRef.current) {
        const AudioContextClass = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
        if (AudioContextClass) {
          audioCtxRef.current = new AudioContextClass();
        }
      }

      const ctx = audioCtxRef.current;
      if (!ctx) return;

      if (ctx.state === 'suspended') {
        ctx.resume().catch(() => {});
        return;
      }

      const now = ctx.currentTime;
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();

      // 偶数秒と奇数秒で少しピッチを変えて自然なチクタク音を再現
      osc.type = 'triangle';
      osc.frequency.setValueAtTime(isHighTick ? 1400 : 900, now);
      osc.frequency.exponentialRampToValueAtTime(120, now + 0.025);

      gain.gain.setValueAtTime(0.08, now);
      gain.gain.exponentialRampToValueAtTime(0.0001, now + 0.025);

      osc.connect(gain);
      gain.connect(ctx.destination);

      osc.start(now);
      osc.stop(now + 0.025);
    } catch {
      // 音声再生エラーのフォールバック
    }
  }, []);

  // 高精度リアルタイム時計ループ（requestAnimationFrame）
  useEffect(() => {
    let animFrameId: number;

    const tick = () => {
      const now = new Date();
      const currentSeconds = now.getSeconds();

      // 秒が切り替わった瞬間に効果音判定
      if (currentSeconds !== lastSecondRef.current) {
        lastSecondRef.current = currentSeconds;
        if (settings.soundEnabled) {
          playTickSound(currentSeconds % 2 === 0);
        }
      }

      setTime(formatTimeData(now));
      animFrameId = requestAnimationFrame(tick);
    };

    animFrameId = requestAnimationFrame(tick);

    return () => {
      cancelAnimationFrame(animFrameId);
    };
  }, [settings.soundEnabled, playTickSound]);

  // AudioContextクリーンアップ
  useEffect(() => {
    return () => {
      if (audioCtxRef.current && audioCtxRef.current.state !== 'closed') {
        audioCtxRef.current.close().catch(() => {});
      }
    };
  }, []);

  return (
    <div className={`clock-app theme-${settings.theme}`}>
      <main className="clock-container">
        {/* 時計本体カード */}
        <section className="clock-card" aria-label="時計表示部">
          <AnalogClock
            time={time}
            theme={settings.theme}
            movement={settings.movement}
          />

          {/* デジタル情報表示（時刻・日付） */}
          {(settings.showDigital || settings.showDate) && (
            <div className="digital-display" aria-live="off">
              {settings.showDigital && (
                <div className="digital-time" aria-label={`現在時刻 ${time.timeString}`}>
                  {time.timeString}
                </div>
              )}
              {settings.showDate && (
                <div className="digital-date" aria-label={`現在日付 ${time.dateString}`}>
                  {time.dateString}
                </div>
              )}
            </div>
          )}
        </section>

        {/* 時計設定コントロール */}
        <ClockControls
          settings={settings}
          onUpdateSettings={handleUpdateSettings}
        />

        {/* 補足フッター情報 */}
        <footer className="footer-info">
          高精度リアルタイム アナログ時計 Webアプリ
        </footer>
      </main>
    </div>
  );
};

export default App;
